const MENU={"وجبة العائلة": 475, "وجبة الصحبة": 640, "وجبة الشلة": 820, "وجبة الاتنين": 290, "وجبة الغدا": 150, "وجبة الطالب": 85, "برجر كلاسيك": 95, "تشيز برجر دبل": 135, "برجر حار": 120, "كرسبي ساندوتش": 85, "شاورما فراخ": 70, "شاورما لحم": 90, "حواوشي": 75, "هوت دوج": 60, "كفتة مشوية": 140, "كباب": 190, "ريش ضاني": 320, "نص فراخ مشوية": 130, "سمك مشوي": 210, "مكس جريل": 390, "كرسبي 5 قطع": 110, "كرسبي 8 قطع": 165, "أجنحة بافلو": 105, "ستربس دجاج": 95, "بوبكورن دجاج": 80, "فراخ بالجبنة": 115, "بطاطس مقرمشة": 40, "أرينج": 45, "سلطة سيزر": 55, "أرز بسمتي": 35, "بطاطس ودجز": 50, "فلافل": 30, "ثومية": 10, "عيش بلدي": 10, "تشيز كيك": 75, "براوني": 60, "أم علي": 55, "كب كيك": 45, "آيس كريم": 50, "فطير مشلتت بالعسل": 70, "كولا": 25, "ليمون بالنعناع": 35, "عصير برتقال": 40, "عصير مانجو": 45, "ميلك شيك فانيليا": 60, "ميلك شيك شوكولاتة": 60, "مياه معدنية": 10, "قهوة تركي": 30, "شاي بالنعناع": 20}; // نفس منيو الموقع
const ETA_MINUTES=45, OWNER_EMAIL='owner@example.com'; // عدّلهما
const b=$('Webhook - New Order').item.json.body||{};
const u=($json.users||[])[0]; const errors=[];
if(!u||!u.email) errors.push('انتهت الجلسة، سجّل دخول تاني');
const name=String(b.customer_name||'').trim()||(u&&u.displayName)||'';
const phone=String(b.phone||'').trim();
const items=Array.isArray(b.items)?b.items:[];
if(name.length<2) errors.push('الاسم مطلوب');
if(!/^01[0125]\d{8}$/.test(phone)) errors.push('رقم الموبايل غير صحيح');
if(!items.length||items.length>45) errors.push('السلة فاضية');
let total=0,qty=0; const parts=[];
for(const it of items){const q=Number(it&&it.qty),n=String(it&&it.name||'');
 if(!Object.hasOwn(MENU,n)||!Number.isInteger(q)||q<1||q>20){errors.push('صنف أو كمية غير صحيحة');break}
 total+=MENU[n]*q;qty+=q;parts.push(n+' ×'+q);}
const order_id='ORD-'+Date.now().toString().slice(-7);
return {json:{valid:errors.length===0,errors,ownerEmail:OWNER_EMAIL,etaMinutes:ETA_MINUTES,email:u?u.email:'',order:{order_id,customer_name:name,phone,item:parts.join(' + '),quantity:qty,total}}};
